-- 📚 꼭집 주거 사전 — 총자산 3.45억 · 자동차 4,542만 · 국민·행복·매입·통합공공 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.5초 · 결과:
-- {"n": 150, "by_std": {"국민임대": 89, "매입임대": 32, "전세임대": 2, "통합공공임대": 4, "행복주택": 22, "행복주택(신혼희망)": 1}, "all_asset_anns": 203, "ex": ["SH_310650", "20652_1_서울특별시_영등포구", "20648_1_경기도_광명시", "20647_1_경기도_광명시"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('n',(select count(distinct announcement_id) from e where asset_limit=345000000 and car_limit=45420000),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit=345000000 and car_limit=45420000 group by 1)q),'all_asset_anns',(select count(distinct announcement_id) from e where asset_limit is not null),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=345000000 and car_limit=45420000 order by 1 desc limit 4)q))j;
